import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Entry, Personnel, Station } from '../types'
import { HELPER } from './helper'

let HOST = 'halo' // ssh alias of the game box (userConfig `host`); the password never leaves it, read from ~/reclaimer/.env there
let OPERATOR = 'finn' // the admin-log name for the pane and /halo (userConfig `operator`); the model's tool signs as 'claude'
const PANE = 'oni-halo'
const POLL_MS = 20_000

// oni-rcon's palette
const AMBER = '#D9A441', CYAN = '#4FC3D9', RED = '#E5484D', GREEN = '#5FB98A', DIM = '#5C6773', WHITE = '#D6DCE4', GOLD = '#FFD27A'
const TEAM: Record<string, string> = { red: '#E5484D', blue: '#4C8DFF', green: '#4CC27A', orange: '#F08A24', purple: '#A066E0', gold: '#E8C547', brown: '#A0714A', pink: '#F07FB8' }
const TEAMS = Object.keys(TEAM)
const FREE_TEXT: Record<string, number> = { say: 0, tell: 1, kick: 1, servername: 0 } // last argument = rest of the line
const READ_ONLY = new Set(['status', 'players', 'maps', 'modes', 'bans', 'vpn', 'help'])

const stations = atom({ plugin: 'oni-halo', key: 'stations' } as const, [])
const selected = atom({ plugin: 'oni-halo', key: 'selected' } as const, 0)
const log = atom({ plugin: 'oni-halo', key: 'log' } as const, [])
const isDenied = atom({ plugin: 'oni-halo', key: 'isDenied' } as const, false)
const isBusy = atom({ plugin: 'oni-halo', key: 'isBusy' } as const, false)
const synced = atom({ plugin: 'oni-halo', key: 'synced' } as const, '')

type Reply = { port: number; command: string; server?: string; ok: boolean; text?: string; data?: any; denied?: boolean }

/** A console line as its target (`@all`, `@2`, `@mlg`, `@49176`) and words; say/tell/kick/servername keep the rest of the line whole. */
export function parseLine(line: string): { at?: string; words: string[] } {
  let s = line.trim(), at: string | undefined
  if (s.startsWith('@')) {
    const end = s.search(/\s|$/)
    at = s.slice(1, end)
    s = s.slice(end).trim()
  }
  const token = /\s*(?:"([^"]*)"|(\S+))/y
  const words: string[] = []
  let pos = 0
  const take = () => {
    token.lastIndex = pos
    const m = token.exec(s)
    if (!m) return false
    words.push(m[1] ?? m[2] ?? '')
    pos = token.lastIndex
    return true
  }
  take()
  const lead = FREE_TEXT[(words[0] ?? '').toLowerCase()]
  if (lead === undefined) {
    while (take());
    return { at, words }
  }
  while (words.length <= lead && take());
  let rest = s.slice(pos).trim()
  const q = rest[0]
  if (rest.length > 1 && (q === '"' || q === "'") && rest.endsWith(q) && !rest.slice(1, -1).includes(q)) rest = rest.slice(1, -1)
  if (rest) words.push(rest)
  return { at, words }
}

/** The ports a target names: none means the selected station, `all` every one (0 = the box fans out). */
export function pick(list: Station[], at: string | undefined, sel: number): number[] {
  if (at === undefined) return sel ? [sel] : []
  if (at.toLowerCase() === 'all') return [0]
  const n = Number(at)
  if (Number.isInteger(n) && n >= 1 && n <= list.length) return [list[n - 1]!.port]
  if (Number.isInteger(n) && n > 1024) return [n]
  return list.filter(s => s.name.toLowerCase().includes(at.toLowerCase())).map(s => s.port)
}

/** Names with the tag they all share cut off: "Arche Labs | OCE Slayer" -> "Slayer". */
export function shortNames(names: string[]): string[] {
  if (names.length < 2) return names
  let p = names[0]!
  for (const n of names) while (!n.startsWith(p)) p = p.slice(0, -1)
  const cut = Math.max(p.lastIndexOf(' '), 0)
  return names.map(n => n.slice(cut).replace(/^[\s|·:-]+/, '') || n)
}

const b64 = (s: string) => btoa(String.fromCharCode(...new TextEncoder().encode(s)))
const clock = () => new Date().toTimeString().slice(0, 8)
const pad = (s: string, n: number) => (s.length > n ? s.slice(0, n - 1) + '…' : s.padEnd(n))
const num = (v: unknown) => (typeof v === 'number' ? v : Number(v) || 0)

async function rcon($: EngineInterface, by: string, batch: (string | number)[][]): Promise<Reply[]> {
  const r = await $.process.run(
    ['ssh', '-o', 'BatchMode=yes', '-o', 'ConnectTimeout=8', HOST, 'python3', '-', b64(by), b64(JSON.stringify(batch))],
    { stdin: HELPER, timeoutMs: 60_000 },
  )
  if (r.exitCode !== 0) throw new Error(r.stderr.trim().split('\n').pop() || `ssh exited ${r.exitCode}`)
  return JSON.parse(r.stdout)
}

function personnel(p: any): Personnel {
  const t = p.team
  return {
    id: String(p.id ?? ''), name: String(p.name ?? '?'), tag: String(p.service_tag ?? ''),
    team: typeof t === 'number' ? TEAMS[t] ?? '' : t ? String(t).toLowerCase() : '',
    score: num(p.score), kills: num(p.kills), deaths: num(p.deaths), isAdmin: !!p.admin,
  }
}

let inFlight = false // ponytail: one sync at a time; a poll that lands mid-sync is skipped, not queued

async function refresh($: EngineInterface) {
  if (inFlight) return
  inFlight = true
  await update($, isBusy, () => true)
  try {
    const replies = await rcon($, OPERATOR, [[0, 'status'], [0, 'players']])
    const byPort = new Map<number, Station>()
    for (const r of replies) {
      const s = byPort.get(r.port) ?? { port: r.port, name: r.server ?? String(r.port), isUp: r.ok, text: r.text ?? '', map: '', mode: '', phase: '', players: 0, max: 0, crew: [] }
      if (r.command === 'status' && r.ok) Object.assign(s, { name: r.data?.name ?? s.name, map: r.data?.map ?? '', mode: r.data?.mode ?? '', phase: r.data?.phase ?? '', players: num(r.data?.players), max: num(r.data?.max_players) })
      if (r.command === 'players' && r.ok) s.crew = (r.data?.players ?? []).map(personnel)
      s.isUp &&= r.ok
      if (!r.ok) s.text = r.text ?? 'no reply'
      byPort.set(r.port, s)
    }
    const list = [...byPort.values()]
    await update($, stations, () => list)
    await update($, isDenied, () => replies.some(r => r.denied))
    await update($, selected, sel => (list.some(s => s.port === sel) ? sel : list[0]?.port ?? 0))
    await update($, synced, () => clock())
  } catch (err) {
    $.ui.toast(`ONI: sync failed: ${(err as Error).message}`)
  } finally {
    inFlight = false
    await update($, isBusy, () => false)
  }
}

/** Runs one console line and logs it; resolves the replies as text. */
async function execute($: EngineInterface, by: string, line: string, readOnly = false): Promise<string> {
  const { at, words } = parseLine(line)
  if (!words.length) return 'Nothing to send.'
  const cmd = words[0]!.toLowerCase()
  if (readOnly && !READ_ONLY.has(cmd)) throw new Error(`'${cmd}' changes the server; Finn runs it from the ONI pane or /halo. Read-only here: ${[...READ_ONLY].join(', ')}.`)
  const list = await read($, stations)
  const ports = pick(list, at, await read($, selected))
  if (!ports.length) throw new Error(at ? `No station matches @${at}.` : 'No station selected yet: refresh first, or name one with @.')
  const replies = await rcon($, by, ports.map(p => [p, cmd, ...words.slice(1)]))
  const names = new Map(list.map((s, i) => [s.port, shortNames(list.map(x => x.name))[i]!]))
  const entries: Entry[] = replies.map(r => ({ at: clock(), where: names.get(r.port) ?? String(r.port), line: words.join(' '), isOk: r.ok, text: r.text ?? '' }))
  await update($, log, l => [...l, ...entries].slice(-60))
  if (!READ_ONLY.has(cmd)) void refresh($)
  return entries.map(e => `[${e.where}] ${e.isOk ? '' : 'FAILED: '}${e.text}`).join('\n')
}

export const register: Register = (on, options) => {
  HOST = String(options.host ?? HOST)
  OPERATOR = String(options.operator ?? OPERATOR)
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'halo', description: 'ONI RCON console for the Halo servers (no args: open the pane)', argumentHint: '[@server|@all] <command> [args]' })
    await $.tool.register({
      name: 'rcon',
      description: 'Read-only RCON on the Project Reclaimer (Halo 3) dedicated servers behind the configured ssh host. `command` is one console line: status, players, maps, modes, bans, vpn or help. `server` is "all", a 1-based station number, a port, or part of a name; default the station selected in the ONI pane.',
      inputSchema: { type: 'object', properties: { command: { type: 'string' }, server: { type: 'string' } }, required: ['command'] },
    })
    $.clock.every(POLL_MS, async () => {
      if (await read($, isDenied)) return // never hammer a refused password: 5 in 10 min locks the address out
      if ((await $.ui.panes()).some(p => p.id === PANE)) await refresh($)
    })
    return next(e)
  })

  on('command.run', { command: 'halo' }, async ($, e) => {
    if (!e.args.trim()) {
      await $.ui.open({ id: PANE, title: 'ONI · Section Three' })
      void refresh($)
      return { text: 'ONI remote console open.' }
    }
    if (!(await read($, stations)).length) await refresh($)
    try {
      return { text: await execute($, OPERATOR, e.args) }
    } catch (err) {
      return { text: (err as Error).message }
    }
  })

  on('tool.call', { tool: 'mcp__oni-halo__rcon' }, async ($, e) => {
    const { command = '', server } = e as unknown as { command?: string; server?: string }
    try {
      if (!(await read($, stations)).length) await refresh($)
      return { result: await execute($, 'claude', (server ? `@${server.replace(/\s+/g, '')} ` : '') + command, true) }
    } catch (err) {
      return { deny: (err as Error).message }
    }
  }).catch(() => ({ deny: 'oni-halo: the RCON guard failed, so nothing was sent.' }))

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const ui = $.ui.resolve(e)
    const { Box, Text, Button } = ui
    const width = Math.max(40, e.props.bodyColumns ?? e.viewport?.columns ?? 80)
    const list = await read($, stations)
    const sel = await read($, selected)
    const entries = await read($, log)
    const denied = await read($, isDenied)
    const busy = await read($, isBusy)
    const names = shortNames(list.map(s => s.name))
    const cur = list.find(s => s.port === sel)
    const crew = list.reduce((n, s) => n + s.crew.length, 0)
    const [cond, condColor] = denied ? ['RED · SIGN-IN REFUSED', RED] : list.some(s => !s.isUp) ? ['AMBER', AMBER] : ['GREEN', GREEN]
    const rule = (label: string) => <Text color={DIM}>── <Text color={AMBER} bold>{label}</Text> {'─'.repeat(Math.max(0, width - label.length - 5))}</Text>
    const nameW = Math.min(18, Math.max(8, ...names.map(n => n.length)))
    const room = Math.max(3, (e.viewport?.rows ?? 30) - list.length - 16)

    return (
      <Box flexDirection="column">
        <Box justifyContent="space-between">
          <Text color={AMBER} bold>▲ OFFICE OF NAVAL INTELLIGENCE</Text>
          <Text color={condColor} bold> CONDITION {cond} </Text>
        </Box>
        <Text color={DIM}>
          SECTION THREE · REMOTE CONSOLE TERMINAL · <Text color={RED}>TOP SECRET</Text>
        </Text>
        <Text color={DIM}>
          {HOST} · {list.length} stations · {crew} personnel · {busy ? <Text color={GOLD}>▒ SYNCING</Text> : `synced ${(await read($, synced)) || 'never'}`}
        </Text>
        {rule('STATIONS')}
        {list.length === 0 && <Text color={DIM}>{busy ? 'Establishing uplink to the game box…' : 'No uplink yet. Press r.'}</Text>}
        {list.map((s, i) => (
          <Box key={`st${s.port}`}>
            <Button key={`sel${s.port}`} plain hotkey={i < 9 ? String(i + 1) : undefined} label={`${s.port === sel ? '▶' : ' '} ${pad(names[i]!, nameW)}`} onPress={() => update($, selected, () => s.port)} />
            <Text color={s.isUp ? GREEN : RED}> ● </Text>
            {s.isUp ? (
              <Text color={s.port === sel ? WHITE : DIM} wrap="truncate">
                {pad(`${s.mode} on ${s.map}`, 26)} {pad(s.phase.replace(/_/g, ' '), 10)} <Text color={s.players ? CYAN : DIM}>{s.players}/{s.max}</Text>
              </Text>
            ) : (
              <Text color={RED} wrap="truncate">{s.text}</Text>
            )}
          </Box>
        ))}
        {rule(`ASSETS · ${cur ? names[list.indexOf(cur)] : '—'}`)}
        {cur && cur.crew.length === 0 && <Text color={DIM}>No personnel deployed.</Text>}
        {cur?.crew.map(p => (
          <Text key={`p${p.id}`} wrap="truncate">
            <Text color={TEAM[p.team] ?? DIM}>█ </Text>
            <Text color={GOLD}>{pad(p.tag, 5)}</Text>
            <Text color={WHITE}>{pad(p.name, 18)}</Text>
            <Text color={DIM}> score </Text><Text color={CYAN}>{String(p.score).padStart(3)}</Text>
            <Text color={DIM}>  K/D </Text><Text color={WHITE}>{p.kills}/{p.deaths}</Text>
            {p.isAdmin && <Text color={AMBER}>  ADMIN</Text>}
            <Text color={DIM}>  {p.id.slice(0, 8)}</Text>
          </Text>
        ))}
        {rule('CONSOLE')}
        <Text color={DIM}>
          Commands go to the ▶ station · <Text color={CYAN}>@all</Text>, <Text color={CYAN}>@2</Text> or <Text color={CYAN}>@mlg</Text> first to aim elsewhere · <Text color={CYAN}>help</Text> lists them
        </Text>
        {'Input' in ui && e.surface !== 'mobile' && (
          <ui.Input key="console" placeholder="say Lobby restarts in 5" submitLabel="Transmit" onSubmit={line => void execute($, OPERATOR, line).catch(err => $.ui.toast(`ONI: ${(err as Error).message}`))} />
        )}
        {entries.slice(-room).map((l, i) => (
          <Text key={`log${i}`} wrap="truncate">
            <Text color={DIM}>{l.at} </Text>
            <Text color={CYAN}>{pad(l.where, 10)} </Text>
            <Text color={WHITE}>› {l.line} </Text>
            <Text color={l.isOk ? GREEN : RED}>{l.isOk ? '✓' : '✗'} {l.text.split('\n')[0]}</Text>
          </Text>
        ))}
        <Box gap={1} marginTop={1}>
          <Button key="refresh" hotkey="r" label="Refresh" variant="primary" onPress={() => refresh($)} />
          <Button key="close" role="dismiss" label="Close" onPress={() => $.ui.close({ id: PANE })} />
        </Box>
      </Box>
    )
  })
}

