// The RCON client run on the game box over ssh: stdlib only, so the game box needs nothing installed.
export const HELPER = String.raw`import base64, json, os, re, socket, struct, sys

# ponytail: stdlib WebSocket client so the game box needs nothing installed; argv: base64 by, base64 JSON [[port, cmd, *args], ...]
def frame(s, d):
    m, n = os.urandom(4), len(d)
    h = bytes([0x81]) + (bytes([0x80 | n]) if n < 126 else bytes([0xFE]) + struct.pack(">H", n) if n < 65536 else bytes([0xFF]) + struct.pack(">Q", n))
    s.sendall(h + m + bytes(b ^ m[i % 4] for i, b in enumerate(d)))

def recv(s, f):
    buf = b""
    while True:
        hd = f.read(2)
        if len(hd) < 2: raise ConnectionError("connection closed")
        n = hd[1] & 127
        if n == 126: n = struct.unpack(">H", f.read(2))[0]
        elif n == 127: n = struct.unpack(">Q", f.read(8))[0]
        mask = f.read(4) if hd[1] & 128 else None
        p = f.read(n)
        if mask: p = bytes(b ^ mask[i % 4] for i, b in enumerate(p))
        op = hd[0] & 15
        if op == 8: raise ConnectionError("server closed the connection")
        if op == 9: s.sendall(bytes([0x8A, 0x80 | len(p)]) + b"\0\0\0\0" + p); continue
        if op in (1, 2, 0): buf += p
        if hd[0] & 128 and op != 10 and buf:
            return json.loads(buf)

def password():
    for line in open(os.path.expanduser("~/reclaimer/.env"), encoding="utf-8"):
        if line.startswith("RECLAIMER_DEDICATED_RCON_PASSWORD="):
            return line.split("=", 1)[1].strip().strip('"')
    raise SystemExit("no RECLAIMER_DEDICATED_RCON_PASSWORD in ~/reclaimer/.env")

def session(port, calls, by, pw):
    out = []
    try:
        s = socket.create_connection(("127.0.0.1", port), 5); s.settimeout(10)
        k = base64.b64encode(os.urandom(16)).decode()
        s.sendall(f"GET / HTTP/1.1\r\nHost: 127.0.0.1:{port}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: {k}\r\nSec-WebSocket-Version: 13\r\n\r\n".encode())
        f = s.makefile("rb")
        if b" 101 " not in f.readline(): raise ConnectionError("that port doesn't speak RCON")
        while f.readline() not in (b"\r\n", b""): pass
        frame(s, json.dumps({"type": "auth", "password": pw}).encode())
        a = recv(s, f)
        if not a.get("ok"):  # never retried: 5 wrong passwords in 10 min lock the address out
            return [{"port": port, "command": c[0], "ok": False, "denied": True, "text": a.get("error") or a.get("text") or "sign-in refused"} for c in calls]
        for i, (cmd, *args) in enumerate(calls, 1):
            frame(s, json.dumps({"type": "command", "command": cmd, "args": [str(x) for x in args], "id": i, "by": by}).encode())
            while (r := recv(s, f)).get("type") != "reply" or r.get("id") != i: pass  # skip pushed events
            out.append({"port": port, "command": cmd, "server": a.get("server"), **r})
        s.close()
    except (OSError, ValueError, ConnectionError) as e:
        out += [{"port": port, "command": c[0], "ok": False, "text": str(e) or type(e).__name__} for c in calls[len(out):]]
    return out

def ports():  # every [[server]] port in dedicated.toml: a server added there shows up here with no edit
    text = open(os.path.expanduser("~/reclaimer/server/dedicated.toml"), encoding="utf-8").read()
    text = re.split(r"(?m)^\[\[server\]\]", text)[1:]  # at line start: the comments mention [[server]] too
    return [int(m.group(1)) for b in text if (m := re.search(r"(?m)^rcon_port\s*=\s*(\d+)", b) or re.search(r"(?m)^port\s*=\s*(\d+)", b))]

by, batch = (base64.b64decode(x).decode() for x in sys.argv[1:3])  # base64: survives the ssh remote shell
pw, groups = password(), {}
for port, *call in json.loads(batch):  # port 0 = every server
    for p in ports() if int(port) == 0 else [int(port)]: groups.setdefault(p, []).append(call)
print(json.dumps([r for port, calls in groups.items() for r in session(port, calls, by, pw)]))
`

