export type Personnel = { id: string; name: string; tag: string; team: string; score: number; kills: number; deaths: number; isAdmin: boolean }
export type Station = { port: number; name: string; isUp: boolean; text: string; map: string; mode: string; phase: string; players: number; max: number; crew: Personnel[] }
export type Entry = { at: string; where: string; line: string; isOk: boolean; text: string }

declare module 'claude-code' {
  interface PluginState {
    'oni-halo': { stations: Station[]; selected: number; log: Entry[]; isDenied: boolean; isBusy: boolean; synced: string }
  }
}
